proposed_sdl:
enum LoginApplication { CUSTOMER MERCHANT RIDER ADMIN }
enum IdentityRole { CUSTOMER MERCHANT_STAFF RIDER ADMIN }
enum EmailVerificationStatus { UNVERIFIED VERIFIED }
scalar UUID
scalar DateTime
input CustomerRegistrationInput { email: String!, password: String!, displayName: String! }
input PasswordLoginInput { email: String!, password: String!, application: LoginApplication! }
input SessionRefreshInput { refreshToken: String! }
type IdentityUser { id: UUID!, email: String!, displayName: String!, roles: [IdentityRole!]!, emailVerificationStatus: EmailVerificationStatus! }
type SessionPayload { accessToken: String!, refreshToken: String!, accessTokenExpiresAt: DateTime!, refreshTokenExpiresAt: DateTime!, user: IdentityUser! }
type MutationAcknowledgement { accepted: Boolean! }
extend type Query { me: IdentityUser! }
extend type Mutation {
 registerCustomer(input: CustomerRegistrationInput!): SessionPayload!
 loginPassword(input: PasswordLoginInput!): SessionPayload!
 refreshSession(input: SessionRefreshInput!): SessionPayload!
 logoutSession(input: SessionRefreshInput!): MutationAcknowledgement!
 logoutAllSessions: MutationAcknowledgement!
}
